// afdEP FP8 combine replies (opt-in, AFDEP_HYBRID_FP8_COMBINE=1, csrc/kernels/elastic/afdep_suites.hpp).
// On the directional hybrid an FFN forwarder sends each reduced reply row to an Attention domain as
// E4M3 with one power-of-two scale per 128 elements instead of BF16, and the Attention reduce
// epilogue dequantizes each FFN domain's row and sums them, with any bias, in FP32 before rounding
// once to BF16. The NVLink (scale-up) partials stay BF16. Only the copies generated by
// tests/role_kernels.py use this header. Lossy, and visible on the wire: every rank must resolve
// the switch alike (the Buffer latches it at construction and afdep/deepep.py checks it).
#pragma once

#include <type_traits>

#include <deep_ep/common/compiled.cuh>
#include <deep_ep/common/exception.cuh>
#include <deep_ep/common/layout.cuh>
#include <deep_ep/common/ptx.cuh>

#ifndef DISABLE_SM90_FEATURES
#include <cuda_fp16.h>
#endif

namespace deep_ep::elastic {

// Reply row (scale-out recv inbox and FFN staging), no metadata (expanded layout, no top-k weights):
//   [0, H)                     E4M3 values, element order unchanged
//   [H, H + align32(H / 128))  byte g = 127 + e_g, the UE8M0 exponent of group g's scale 2^e_g
//                              (elements [128 g, 128 g + 128)); groups 4p..4p+3 form sf_pack_t p
//                              (ue8m0x4, little-endian), DeepEP's dispatch packing
// 4,128 bytes at H = 4096 instead of the BF16 row's 8,256.
constexpr int kAfdFp8GroupSize = 128;
// e_g is the smallest integer with amax_g <= 448 * 2^e_g (448 = 1.75 * 2^8, the E4M3 maximum),
// exact from amax's FP32 bits: biased exponent - (127 + 8), plus one when the mantissa exceeds
// 0.75 (0x600000). A group's amax then maps into (224, 448].
constexpr int kAfdFp8ExponentBias = 135;
constexpr int kAfdFp8MantissaThreshold = 0x600000;
// The clamp (zero or tiny groups) keeps 2^e and 2^-e normal and every nonzero dequantized value
// (at least the E4M3 minimum 2^-9 times 2^e) an FP32 normal, so scaling, dequantizing and the
// fused accumulate below are exact products: the only rounding is the E4M3 cast (nearest even).
// The exception is the top scale 2^120 (amax above 448 * 2^119, or an infinity): 448 * 2^120 is
// not a finite FP32, so a group amax of 248 * 2^120 or more decodes to infinity.
constexpr int kAfdFp8MinExponent = -117;

template <int kHidden>
__forceinline__ __device__ __host__ layout::TokenLayout afdep_fp8_combine_layout() {
    // A 128-element group then always lies inside one warp-wide row of vectors
    EP_STATIC_ASSERT(kHidden % 256 == 0, "FP8 combine: hidden must divide by 256");
    return layout::TokenLayout(kHidden, kHidden / kAfdFp8GroupSize, 0, false);
}

#ifndef DISABLE_SM90_FEATURES

__forceinline__ __device__ int afdep_fp8_exponent(const float& amax) {
    const int bits = __float_as_int(amax);
    const int e = ((bits >> 23) & 0xff) - kAfdFp8ExponentBias + ((bits & 0x7fffff) > kAfdFp8MantissaThreshold ? 1 : 0);
    return max(e, kAfdFp8MinExponent);
}

// 2^e for e in [-126, 127], built from its bits (exact)
__forceinline__ __device__ float afdep_fp8_pow2(const int& e) {
    return __int_as_float((127 + e) << 23);
}

// Predicated non-coherent loads (zeros when value < 0), as ptx::ldg_with_gez_pred
__forceinline__ __device__ uint2 afdep_ldg_with_gez_pred(const uint2* ptr, const int& value,
                                                         const ptx::TMACacheHint& cache_hint = ptx::TMACacheHint::kEvictFirst) {
    uint2 ret = make_uint2(0, 0);
    asm volatile(
        "{\n\t"
        "  .reg .pred p;\n\t"
        "  setp.ge.s32 p, %3, 0;\n\t"
        "  @p ld.L1::no_allocate.L2::cache_hint.global.nc.v2.s32 {%0, %1}, [%2], %4;\n\t"
        "}"
        : "+r"(ret.x), "+r"(ret.y)
        : "l"(ptr), "r"(value), "l"(cache_hint)
        : "memory");
    return ret;
}

__forceinline__ __device__ uint4 afdep_ldg_with_gez_pred(const uint4* ptr, const int& value,
                                                         const ptx::TMACacheHint& cache_hint = ptx::TMACacheHint::kEvictFirst) {
    const auto ret = ptx::ldg_with_gez_pred(reinterpret_cast<const int4*>(ptr), value, cache_hint);
    return make_uint4(static_cast<uint32_t>(ret.x), static_cast<uint32_t>(ret.y),
                      static_cast<uint32_t>(ret.z), static_cast<uint32_t>(ret.w));
}

__forceinline__ __device__ uint32_t afdep_ldg_with_gez_pred(const uint32_t* ptr, const int& value,
                                                            const ptx::TMACacheHint& cache_hint = ptx::TMACacheHint::kEvictFirst) {
    uint32_t ret = 0;
    asm volatile(
        "{\n\t"
        "  .reg .pred p;\n\t"
        "  setp.ge.s32 p, %2, 0;\n\t"
        "  @p ld.L1::no_allocate.L2::cache_hint.global.nc.s32 %0, [%1], %3;\n\t"
        "}"
        : "+r"(ret)
        : "l"(ptr), "r"(value), "l"(cache_hint)
        : "memory");
    return ret;
}

// The FP8 bytes of one BF16 vector (8 elements on SM90, 16 on SM100)
template <typename vec_t>
using afdep_fp8_pack_t = std::conditional_t<sizeof(vec_t) / sizeof(nv_bfloat16) == 8, uint2, uint4>;

// FFN forwarder: store vector `vec_idx` of a reduced BF16 row as E4M3 into the row at
// `dst_buffer_ptr` (the warp's shared-memory TMA row, which then holds the FP8 reply row). Every
// lane of the warp calls it for its vector of one warp-wide row: a group of 128 elements is
// 128 / E consecutive lanes, which agree on the group's amax through shuffles, and the group's
// first lane writes the scale byte. NaN stays NaN at its own element (fmaxf ignores it in the
// amax); an infinity sets the group's scale to 2^120, so it decodes to infinity and the group's
// other elements flush to zero unless they are near the BF16 range limit.
template <int kHiddenVec, typename vec_t>
__forceinline__ __device__ void afdep_fp8_store_vec(const vec_t& value, const int& vec_idx, const int& lane_idx,
                                                    vec_t* dst_buffer_ptr) {
    constexpr int kNumElemsPerVec = sizeof(vec_t) / sizeof(nv_bfloat16);
    constexpr int kNumLanesPerGroup = kAfdFp8GroupSize / kNumElemsPerVec;
    using pack_t = afdep_fp8_pack_t<vec_t>;
    EP_STATIC_ASSERT(kNumElemsPerVec == 8 or kNumElemsPerVec == 16, "FP8 combine: invalid vector");
    EP_STATIC_ASSERT(sizeof(pack_t) == kNumElemsPerVec, "FP8 combine: invalid pack");
    EP_STATIC_ASSERT((kHiddenVec * kNumElemsPerVec) % 256 == 0, "FP8 combine: hidden must divide by 256");

    // Group amax
    const auto bf162_view = reinterpret_cast<const nv_bfloat162*>(&value);
    float2 values[kNumElemsPerVec / 2];
    float amax = 0;
    #pragma unroll
    for (int l = 0; l < kNumElemsPerVec / 2; ++ l) {
        values[l] = __bfloat1622float2(bf162_view[l]);
        amax = fmaxf(amax, fmaxf(fabsf(values[l].x), fabsf(values[l].y)));
    }
    #pragma unroll
    for (int mask = kNumLanesPerGroup / 2; mask > 0; mask >>= 1)
        amax = fmaxf(amax, __shfl_xor_sync(0xffffffff, amax, mask));

    // Scale by 2^-e (exact) and round to E4M3 (nearest even; |value| <= 448 by the choice of e)
    const int exponent = afdep_fp8_exponent(amax);
    const float inv_scale = afdep_fp8_pow2(-exponent);
    pack_t packed;
    const auto fp8x2_view = reinterpret_cast<__nv_fp8x2_storage_t*>(&packed);
    #pragma unroll
    for (int l = 0; l < kNumElemsPerVec / 2; ++ l) {
        fp8x2_view[l] = __nv_cvt_float2_to_fp8x2(make_float2(values[l].x * inv_scale, values[l].y * inv_scale),
                                                 __NV_SATFINITE, __NV_E4M3);
    }

    // Values at [vec_idx * E, vec_idx * E + E), the scale byte at H + group
    constexpr int kNumHidden = kHiddenVec * kNumElemsPerVec;
    constexpr int kNumGroups = kNumHidden / kAfdFp8GroupSize;
    constexpr int kNumScaleBytes = (kNumGroups + 31) / 32 * 32;
    const auto row = reinterpret_cast<uint8_t*>(dst_buffer_ptr);
    *reinterpret_cast<pack_t*>(row + vec_idx * kNumElemsPerVec) = packed;
    if (lane_idx % kNumLanesPerGroup == 0) {
        const int group_idx = vec_idx / kNumLanesPerGroup;
        row[kNumHidden + group_idx] = static_cast<uint8_t>(127 + exponent);
        // The last group's lane also zeroes the pad up to the 32-byte-aligned row end: the whole row
        // goes on the wire, and the epilogue's 4-byte scale loads cover up to 3 pad bytes.
        if (group_idx == kNumGroups - 1) {
            #pragma unroll
            for (int b = kNumGroups; b < kNumScaleBytes; ++ b)
                row[kNumHidden + b] = 0;
        }
    }
}

// Attention reduce epilogue: combine_reduce's FP32 path (combine_utils.cuh) over FP8 reply rows.
// `get_src_buffer_ptr_func(slot)` returns the slot's row base. Each FFN domain's row is
// dequantized exactly (E4M3 fits FP16; the scale is a power of two), summed in FP32 in slot order
// with any bias, and rounded once to BF16 into `dst_buffer_ptr`. A slot below zero loads zeros, so
// it adds 0 * 0. There is no BF16-add bypass.
template <int kHiddenVec, int kUnrollFactor, int kNumExpectedTopk, int kNumValidTopk,
          typename vec_t, typename get_src_buffer_ptr_func_t, typename wait_buffer_func_t>
__device__ __forceinline__
void afdep_fp8_combine_dequant_reduce(const int& lane_idx, int (&topk_slot_idx)[kNumValidTopk],
                                      vec_t* dst_buffer_ptr,
                                      const get_src_buffer_ptr_func_t& get_src_buffer_ptr_func,
                                      const wait_buffer_func_t& wait_buffer_func,
                                      vec_t* bias_0 = nullptr, vec_t* bias_1 = nullptr) {
    constexpr int kNumElemsPerVec = sizeof(vec_t) / sizeof(nv_bfloat16);
    constexpr int kNumLanesPerGroup = kAfdFp8GroupSize / kNumElemsPerVec;
    constexpr int kNumHidden = kHiddenVec * kNumElemsPerVec;
    using pack_t = afdep_fp8_pack_t<vec_t>;
    EP_STATIC_ASSERT(kNumElemsPerVec == 8 or kNumElemsPerVec == 16, "FP8 combine: invalid vector");
    EP_STATIC_ASSERT(sizeof(pack_t) == kNumElemsPerVec, "FP8 combine: invalid pack");
    EP_STATIC_ASSERT(kNumHidden % 256 == 0, "FP8 combine: hidden must divide by 256");
    EP_STATIC_ASSERT(kHiddenVec % (kUnrollFactor * 32) == 0, "Invalid unrolling");
    EP_STATIC_ASSERT(kNumValidTopk > 0, "Invalid top-k");

    #pragma unroll 1
    for (int i = 0; i < kHiddenVec / (kUnrollFactor * 32); ++ i) {
        // Add bias
        float2 reduced[kUnrollFactor * kNumElemsPerVec / 2] = {};
        const auto add_bias = [&](const vec_t* base_ptr) {
            // Read
            vec_t values[kUnrollFactor];
            #pragma unroll
            for (int j = 0; j < kUnrollFactor; ++ j)
                values[j] = ptx::ldg(base_ptr + i * (kUnrollFactor * 32) + j * 32 + lane_idx);

            // Reduce
            const auto bf162_view = reinterpret_cast<nv_bfloat162*>(values);
            #pragma unroll
            for (int j = 0; j < kUnrollFactor * kNumElemsPerVec / 2; ++ j)
                ptx::accumulate(reduced[j], bf162_view[j]);
        };
        bias_0 != nullptr ? add_bias(bias_0) : void();
        bias_1 != nullptr ? add_bias(bias_1) : void();

        #pragma unroll
        for (int k = 0; k < kNumValidTopk; ++ k) {
            // We have a limitation on `k` to reduce the branch instruction count
            if (k >= kNumExpectedTopk and topk_slot_idx[k] < 0)
                break;

            // Read values and their groups' scales
            const auto slot_idx = topk_slot_idx[k];
            const auto row = reinterpret_cast<const uint8_t*>(get_src_buffer_ptr_func(slot_idx));
            const auto sf_ptr = reinterpret_cast<const uint32_t*>(row + kNumHidden);
            pack_t values[kUnrollFactor];
            float scales[kUnrollFactor];
            #pragma unroll
            for (int j = 0; j < kUnrollFactor; ++ j) {
                const int vec_idx = i * (kUnrollFactor * 32) + j * 32 + lane_idx;
                const int group_idx = vec_idx / kNumLanesPerGroup;
                values[j] = afdep_ldg_with_gez_pred(reinterpret_cast<const pack_t*>(row + vec_idx * kNumElemsPerVec), slot_idx);
                const auto sf_pack = afdep_ldg_with_gez_pred(sf_ptr + group_idx / 4, slot_idx);
                // 2^e from its byte (a missing slot gives 0)
                scales[j] = __int_as_float(static_cast<int>(((sf_pack >> (8 * (group_idx % 4))) & 0xffu) << 23));
            }

            // Dequantize and reduce
            #pragma unroll
            for (int j = 0; j < kUnrollFactor; ++ j) {
                const auto fp8x2_view = reinterpret_cast<const __nv_fp8x2_storage_t*>(&values[j]);
                #pragma unroll
                for (int l = 0; l < kNumElemsPerVec / 2; ++ l) {
                    const float2 decoded = __half22float2(__half2(__nv_cvt_fp8x2_to_halfraw2(fp8x2_view[l], __NV_E4M3)));
                    auto& sum = reduced[j * (kNumElemsPerVec / 2) + l];
                    sum.x = __fmaf_rn(decoded.x, scales[j], sum.x);
                    sum.y = __fmaf_rn(decoded.y, scales[j], sum.y);
                }
            }
        }

        // Wait buffer releases for the first write
        if (i == 0)
            wait_buffer_func();

        // Cast into shared memory
        #pragma unroll
        for (int j = 0; j < kUnrollFactor; ++ j) {
            vec_t casted_value;
            auto bf162_view = reinterpret_cast<nv_bfloat162*>(&casted_value);
            #pragma unroll
            for (int l = 0; l < kNumElemsPerVec / 2; ++ l)
                bf162_view[l] = __float22bfloat162_rn(reduced[j * (kNumElemsPerVec / 2) + l]);
            dst_buffer_ptr[i * (kUnrollFactor * 32) + j * 32 + lane_idx] = casted_value;
        }
    }
}

#endif

}  // namespace deep_ep::elastic
